START TRANSACTION;
CREATE TABLE "ShowroomProductOptions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "OptionType" character varying(40) NOT NULL,
    "ValueFr" character varying(160) NOT NULL,
    "NormalizedValue" character varying(160) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_ShowroomProductOptions" PRIMARY KEY ("Id")
);

CREATE UNIQUE INDEX "IX_ShowroomProductOptions_OptionType_NormalizedValue" ON "ShowroomProductOptions" ("OptionType", "NormalizedValue");

INSERT INTO "ShowroomProductOptions"
    ("OptionType", "ValueFr", "NormalizedValue", "CreatedAt")
SELECT 'Size', value, normalized, CURRENT_TIMESTAMP
FROM (
    SELECT DISTINCT ON (normalized)
        value, normalized
    FROM (
        SELECT
            BTRIM("Size") AS value,
            TRANSLATE(
                LOWER(BTRIM("Size")),
                'àáâäãåèéêëìíîïòóôöõùúûüÿç',
                'aaaaaaeeeeiiiiooooouuuuyc'
            ) AS normalized
        FROM "ShowroomProducts"
        WHERE NULLIF(BTRIM("Size"), '') IS NOT NULL
    ) AS source
    ORDER BY normalized, value
) AS distinct_values;

INSERT INTO "ShowroomProductOptions"
    ("OptionType", "ValueFr", "NormalizedValue", "CreatedAt")
SELECT 'HairType', value, normalized, CURRENT_TIMESTAMP
FROM (
    SELECT DISTINCT ON (normalized)
        value, normalized
    FROM (
        SELECT
            BTRIM("HairTypeFr") AS value,
            TRANSLATE(
                LOWER(BTRIM("HairTypeFr")),
                'àáâäãåèéêëìíîïòóôöõùúûüÿç',
                'aaaaaaeeeeiiiiooooouuuuyc'
            ) AS normalized
        FROM "ShowroomProducts"
        WHERE NULLIF(BTRIM("HairTypeFr"), '') IS NOT NULL
    ) AS source
    ORDER BY normalized, value
) AS distinct_values;

